{
  "status": "SUPPORTED",
  "task_summary": "Find compatible fastening tool and workpiece, fasten them, and return tool to workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "A tool used to secure or join the workpiece.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "screwdriver",
          "wrench",
          "drill",
          "clamp",
          "battery"
        ],
        "required_properties": [
          "capable_of_fastening",
          "reusable"
        ]
      },
      {
        "id": "workpiece",
        "entity_kind": "OBJECT",
        "function": "The object at the workbench location that requires fastening.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "mechanical_part",
          "assembly_piece",
          "device",
          "component"
        ],
        "required_properties": [
          "needs_fastening",
          "physically_manipulable"
        ]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where the task takes place and where equipment is returned.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "table",
          "bench",
          "desk"
        ],
        "required_properties": [
          "supports_objects",
          "accessible"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "is_compatible",
        "relation": "suitable_for",
        "participant_roles": [
          "fastening_tool",
          "workpiece"
        ]
      ,
        "required": true
      },
      {
        "id": "is_on",
        "relation": "located_at",
        "participant_roles": [
          "workpiece",
          "workbench"
        ]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "identify_components",
        "operation": "search_and_identify",
        "participant_roles": [
          "fastening_tool",
          "workpiece"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "fasten",
        "operation": "apply_fastening",
        "participant_roles": [
          "fastening_tool",
          "workpiece"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "return_equipment",
        "operation": "place_on_surface",
        "participant_roles": [
          "fastening_tool",
          "workbench"
        ]
      ,
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_tool": [
        {
          "label": "yellow_object_on_tray",
          "visual_description": "Yellow rectangular object on the black tray on the desk."
        }
      ],
      "workpiece": [
        {
          "label": "yellow_object_on_tray",
          "visual_description": "Yellow rectangular object on the black tray on the desk."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "desk_drawer_left",
        "label": "Left Desk Drawer",
        "visual_description": "Blue drawer on the left side of the desk with a white handle.",
        "reason": "Closed storage structure that may contain the fastening tool or components."
      },
      {
        "id": "desk_drawer_right",
        "label": "Right Desk Drawer",
        "visual_description": "Blue drawer on the right side of the desk with a white handle.",
        "reason": "Closed storage structure that may contain the fastening tool or components."
      },
      {
        "id": "desk_cabinet",
        "label": "Desk Cabinet",
        "visual_description": "Blue cabinet standing on the right side of the desk with a white handle.",
        "reason": "Closed storage structure that may contain the fastening tool or components."
      }
    ],
    "inspection_order": [
      "black_tray_on_desk",
      "desk_drawer_left",
      "desk_drawer_right",
      "desk_cabinet"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
